def for_dept(code):
    """Every statutory obligation for one department, most severe first."""
    return OBLIGATIONS.get(code, [])


def top_for_dept(code, limit=3):
    """The handful a department head should see without opening the library."""
    return for_dept(code)[:limit]


def counts_for_dept(code):
    """{'critical': n, 'high': n, 'medium': n, 'total': n} for one department."""
    items = for_dept(code)
    out = {"critical": 0, "high": 0, "medium": 0, "total": len(items)}
    for i in items:
        out[i["severity"]] = out.get(i["severity"], 0) + 1
    return out


def all_authorities(codes=None):
    """Distinct regulators across the given departments (all, if None)."""
    codes = codes if codes is not None else list(OBLIGATIONS)
    return sorted({i["authority"] for c in codes for i in for_dept(c) if i["authority"]})


_AUTHORITY_SPLIT = (";", " / ", " and Ministry of ")

# The research came back with both the abbreviation and the spelled-out name
# for a handful of regulators. Folded together so the chip row does not list
# the same body twice.
_AUTHORITY_ALIASES = {
    "uaefiu": "UAE Financial Intelligence Unit",
    "fiu": "UAE Financial Intelligence Unit",
    "fta": "Federal Tax Authority",
    "mohre": "Ministry of Human Resources and Emiratisation",
    "det": "Dubai Department of Economy and Tourism",
    "dld": "Dubai Land Department",
    "rera": "Dubai Land Department",
    "moet": "Ministry of Economy and Tourism",
    "tdra": "TDRA",
    "dha": "Dubai Health Authority",
    "eocn": "Executive Office for Control & Non-Proliferation",
}


def distinct_authorities(codes=None):
    """The same regulators, but split apart and deduplicated for display.

    Several obligations are jointly supervised, so their `authority` field
    reads "Ministry of Economy and Tourism (DNFBP supervisor); UAEFIU". Shown
    verbatim as chips those become unreadable and duplicate each other, so
    each composite is split into its parts and the parenthetical role note is
    dropped — the chip row is a "who regulates us" summary, and the precise
    wording still sits on every individual obligation card.
    """
    codes = codes if codes is not None else list(OBLIGATIONS)
    out = set()
    for raw in all_authorities(codes):
        parts = [raw]
        for sep in _AUTHORITY_SPLIT:
            parts = [bit for part in parts for bit in part.split(sep)]
        for part in parts:
            name = part.split("(")[0].strip(" ,;/")
            if not name:
                continue
            out.add(_AUTHORITY_ALIASES.get(name.lower(), name))
    return sorted(out)


def total_count(codes=None):
    codes = codes if codes is not None else list(OBLIGATIONS)
    return sum(len(for_dept(c)) for c in codes)


def critical_count(codes=None):
    codes = codes if codes is not None else list(OBLIGATIONS)
    return sum(1 for c in codes for i in for_dept(c) if i["severity"] == "critical")


