_GENERIC = {"key": "gov", "abbr": "GOV", "name": "Government authority", "color": "#6d7889", "match": []}


def authority_marks(raw):
    """Every distinct body named in one `authority` string, in priority order.

    An obligation can be jointly supervised ("Ministry of Economy and Tourism
    (DNFBP supervisor); UAE FIU via goAML"), so this returns a list rather than
    a single mark. Longer match tokens are tested first so that, for example,
    "dubai health authority" is not swallowed by a shorter, more generic token.
    """
    text = (raw or "").lower()
    hits = []
    for a in AUTHORITIES:
        for token in sorted(a["match"], key=len, reverse=True):
            if token in text:
                if a["key"] not in [h["key"] for h in hits]:
                    hits.append(a)
                break
    return hits or [_GENERIC]


def authority_mark(raw):
    """The single most relevant body for a string - the first match."""
    return authority_marks(raw)[0]


def authority_label(raw):
    """The text to print beside the mark.

    Where the source string is nothing but the abbreviation the mark already
    shows ("MOHRE", "TDRA"), printing it again reads as a stutter - so the
    full name of the body is substituted instead. Anything more descriptive
    than the bare abbreviation is left exactly as written, because the
    qualifier usually carries meaning ("Ministry of Economy and Tourism (DNFBP
    supervisor)" is not the same claim as "Ministry of Economy and Tourism").
    """
    text = (raw or "").strip()
    marks = authority_marks(text)
    if len(marks) == 1 and text.lower() == marks[0]["abbr"].lower():
        return marks[0]["name"]
    return text


def authorities_for_dept(code):
    """Distinct authority marks across one department, for the section header."""
    out, seen = [], set()
    for item in for_dept(code):
        for mark in authority_marks(item["authority"]):
            if mark["key"] not in seen:
                seen.add(mark["key"])
                out.append(mark)
    return out
